changeSet.sql:
CREATE OR REPLACE FUNCTION nexus_test.analyze_table(target regclass) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ANALYZE %s', target);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.add_fk_not_valid(
    p_table regclass, p_name text, p_column text, p_ref regclass, p_ref_column text, p_extra text
) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY (tenant_id, %I) REFERENCES %s (tenant_id, %I) %s NOT VALID',
        p_table, p_name, p_column, p_ref, p_ref_column, p_extra);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.validate_constraint(p_table regclass, p_name text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER TABLE %s VALIDATE CONSTRAINT %I', p_table, p_name);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.set_force_rls(p_table regclass, p_force boolean) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    IF p_force THEN
        EXECUTE format('ALTER TABLE %s FORCE ROW LEVEL SECURITY', p_table);
    ELSE
        EXECUTE format('ALTER TABLE %s NO FORCE ROW LEVEL SECURITY', p_table);
    END IF;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.drop_constraint(p_table regclass, p_name text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER TABLE %s DROP CONSTRAINT IF EXISTS %I', p_table, p_name);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.add_fk_not_valid_composite3(
    p_table regclass, p_name text, p_col2 text, p_col3 text,
    p_ref regclass, p_ref_col2 text, p_ref_col3 text, p_extra text
) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('ALTER TABLE %s ADD CONSTRAINT %I FOREIGN KEY (tenant_id, %I, %I) REFERENCES %s (tenant_id, %I, %I) %s NOT VALID',
        p_table, p_name, p_col2, p_col3, p_ref, p_ref_col2, p_ref_col3, p_extra);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.grant_execute_on_function(p_signature text, p_role text) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO %I', p_signature, p_role);
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.insert_chunk_bare_vector(
    p_tenant text, p_collection text, p_chash bytea, p_dim int
) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
DECLARE
    v_lit text;
BEGIN
    SELECT '[' || string_agg('0.1', ',') || ']' INTO v_lit FROM generate_series(1, p_dim);
    EXECUTE format(
        'INSERT INTO nexus.chunks (tenant_id, collection, chash, chunk_text, %I) VALUES ($1, $2, $3, $4, $5::vector)',
        'embedding_' || p_dim)
        USING p_tenant, p_collection, p_chash, 'text', v_lit;
END;
$$;

CREATE OR REPLACE FUNCTION nexus_test.drop_index(p_index regclass) RETURNS void
    LANGUAGE plpgsql
    SECURITY INVOKER
AS $$
BEGIN
    EXECUTE format('DROP INDEX %s', p_index);
END;
$$;
